// exec deletes the rows, with their join table rows, in one transaction, and
// returns how many there were.
pub fn (b CommentDelete) exec() !int {
	return b.graph.client.delete(b.data)
}

// comments_by_keys returns the rows with the keys `keys`, in their order.
fn (g Graph) comments_by_keys(keys []string) ![]CommentNode {
	rows := g.comments().where(load.in_keys('id', keys, .int)).all()!
	mut by_key := map[string]CommentNode{}
	for row in rows {
		by_key[row.comment.id.str()] = row
	}
	mut found := []CommentNode{cap: keys.len}
	for key in keys {
		found << by_key[key] or {
			return NotFoundError{
				table: 'comments'
			}
		}
	}
	return found
}
